SELECT MAX(Milliseconds) AS max_ms, MIN(Milliseconds) AS min_ms FROM (SELECT MAX(Milliseconds) AS max_ms, MIN(Milliseconds) AS min_ms FROM (SELECT MAX(Milliseconds) AS max_ms, MIN(Milliseconds) AS min_ms FROM Track WHERE GenreId IN (SELECT GenreId FROM Genre) GROUP BY GenreId) AS subquery) AS subquery
