SELECT 
  C.title, 
  C.credits
FROM 
  classroom C
  JOIN department D ON C.building = D.building
  JOIN course C2 ON C2.course_id = C.course_id
  JOIN student S ON C2.secs_id = S.sec_id
  JOIN instructor I ON C2.instructor_id = I.ID
  JOIN section S2 ON C2.section_id = S2.section_id
  JOIN takes T ON S2.takes_id = T.course_id
  JOIN student S3 ON T.student_id = S3.ID
  JOIN course C3 ON T.course_id = C3.course_id
  JOIN advisor A ON S3.advisor_id = A.ID
  JOIN course C4 ON C3.prereq_id = C4.course_id
WHERE 
  C.title LIKE? 
  AND C.credits > 0
ORDER BY 
  C.title, C.credits DESC;
```

