FROM 
  classroom C
  JOIN 
  department D ON C.building = D.building
  JOIN 
  course C2 ON C2.course_id = C.course_id
  JOIN 
  (SELECT 
  	sec_id, 
  	takes.sec_id, 
  	takes.semester, 
  	takes.year, 
  	takes.grade
  FROM 
  	takes
  JOIN 
  	section S ON takes.sec_id = S.sec_id
  JOIN 
  	instructor I ON S.instructor_ID = I.ID
  WHERE 
  	S.building = C.building AND S.semester = C.semester AND S.year = C.year) AS T2
  ON C2.course_id = T2.course_id
WHERE 
  C2.credits = (
    SELECT 
      MAX(Credits)
    FROM 
      (SELECT 
      	Credits
    FROM 
    	section
    WHERE 
    	building = C.building AND semester = C.semester AND year = C.year) AS T3
  )
ORDER BY 
  C.credits DESC;
```

