  ) o ON c.customer_id = o.customer_id
  JOIN 
  (
    SELECT 
      i.order_id, 
      COUNT(DISTINCT i.order_id) as order_count
    FROM 
      Order_Items oi
      JOIN 
      Invoice_Line_Items il ON oi.order_id = il.order_id
