     AVG(salary) AS avg_salary
   FROM 
     takes
   GROUP BY 
     course_id) T1
  ON D.dept_name = T1.dept_name
GROUP BY 
  D.dept_name
HAVING 
  AVG(T1.avg_salary > (SELECT AVG(salary) FROM instructor) AS avg_instructor_salary)
