SELECT AVG(enrollment) AS avg_enrollment, MAX(enrollment) AS max_enrollment, MIN(enrollment) AS min_enrollment FROM (SELECT SUM(IHSAA_Class) AS enrollment FROM budget WHERE IHSAA_Class IS NOT NULL) AS subquery
