SELECT DISTINCT forename, surname 
FROM drivers 
WHERE id IN (
  SELECT driverid 
  FROM results 
  JOIN races ON results.driverid = races.driverid 
  JOIN constructorstandings ON races.raceid = constructorstandings.raceid 
  JOIN constructors ON constructorstandings.constructorid = constructors.constructorid 
  WHERE statusid = 1 
  AND time < (SELECT MIN(time) FROM results WHERE statusid = 1)
)
