  JOIN address T5 ON T4.address_id = T5.address_id
  JOIN city T6 ON T5.city_id = T6.city_id
  JOIN country T7 ON T6.country_id = T7.country_id
  JOIN film T8 ON T3.film_id = T8.film_id
  JOIN film_category T9 ON T3.film_id = T9.film_id
  JOIN category T10 ON T9.category_id = T10.category_id
  JOIN language T11 ON T8.language_id = T11.language_id
  JOIN inventory T12 ON T3.inventory_id = T12.inventory_id
  JOIN staff T13 ON T3.staff_id = T13.staff_id
  JOIN store T14 ON T3.store_id = T14.store_id
WHERE T1.amount IS NOT
```sql
SELECT 
  MAX(CASE WHEN T2.amount IS NOT NULL THEN T1.amount END) AS max_payment
FROM 
  payment T1
  JOIN payment T2 ON T1.payment_id = T2.payment_id
WHERE 
  T1.last_update = (SELECT MAX(last_update) FROM payment) AND 
