  p.product_name 
FROM 
  Products p 
  JOIN 
  (SELECT DISTINCT T1.product_id 
   FROM 
     Regular_Orders 
     JOIN 
     Regular_Order_Products 
     ON Regular_Orders.regular_order_id = Regular_Order_Products.regular_order_id 
     JOIN 
     Products 
     ON Regular_Order_Products.product_id = Products.product_id 
  ) AS subquery 
ON p.product_id = subquery.product_id
ORDER BY 
