  d.dept_name, 
  AVG(s.stu_gpa) AS avg_gpa
FROM 
  DEPARTMENT d
  JOIN STUDENT s ON d.dept_code = s.dept_code
  JOIN CLASS c ON s.stu_num = c.stu_num
