SELECT 
  a.address_type_code,
  a.address_type_description,
  a.address_id,
  a.line_1,
  a.line_2,
  a.city,
  a.zip_postcode,
  a.state_province_county,
  a.country,
  a.other_address_details,
  a.date_first_rental,
  a.date_left_university,
  a.other_student_details,
  a.monthly_rental,
  b.monthly_rental AS monthly_rental DESC
FROM 
  Addresses a
  JOIN Student_Addresses b ON a.address_id = b.address_id
WHERE 
  b.date_address_from <= (SELECT MAX(date_first_rental) FROM Addresses) AND 
