  PROFESSOR P
  JOIN CLASS C ON P.EMP_NUM = C.PROF_NUM
  JOIN COURSE Q ON C.CRS_CODE = Q.CRS_CODE
WHERE 
  C.CLASS_CODE IN (
    SELECT CLASS_CODE
    FROM CLASS
    WHERE CLASS_SECTION = 'CIS-220'
