SELECT 
  p.name AS park_name, 
  COUNT(DISTINCT a.year) AS attendance
FROM 
  all_star a 
  JOIN 
  player_college pc ON a.player_id = pc.player_id 
  JOIN 
  team t ON a.team_id = t.team_id 
  JOIN 
  home_game hg ON a.year = hg.year 
  JOIN 
  batting b ON a.player_id = b.player_id 
  JOIN 
  fielding f ON a.player_id = f.player_id 
  JOIN 
  postseason ps ON a.year = ps.year 
  JOIN 
  player_award_vote pa ON a.player_id = pa.player_id 
  JOIN 
  player_award pa2 ON pa.player_id = pa2.player_id 
  JOIN 
  manager_award ma ON a.player_id = ma.player_id 
  JOIN 
  manager m ON ma.player_id = m.player_id 
  JOIN 
  team t2 ON m.team_id = t2.team_id 
  JOIN 
  team t ON t2.team_id = t.team_id 
  JOIN 
  fielding_outfield fo ON a.player_id = fo.player_id 
