SELECT DISTINCT T1.Date_Stored
FROM All_Documents AS T1
JOIN Document_Locations AS T2 ON T1.Document_ID = T2.Document_ID
JOIN Ref_Calendar AS T3 ON T1.Date_Stored = T3.Calendar_Date
JOIN Roles AS T4 ON T1.Document_Type_Code = T4.Role_Code
WHERE T1.Document_Name = 'Marry CV';
