  R1.Employee_Name AS Authorised_Employee_Name, 
  D1.Document_Name AS Document_Name
FROM 
  Employees E
  JOIN 
  Documents_to_be_destroyed DT ON E.Employee_ID = DT.Destruction_Authorised_by_Employee_ID
  JOIN 
  All_Documents AD ON DT.Document_ID = AD.Document_ID
