  AND D.outcome_details IS NOT NULL 
  AND D.outcome_code IN ('outcome1', 'outcome2', 'outcome3') 
  AND G.grant_amount > 0
ORDER BY 
  D.document_type_code, 
  D.sent_date, 
  D.response_received_date, 
  G.grant_start_date, 
  G.grant_end_date, 
