SELECT 
  p.product_id, 
  p.product_name, 
  SUM(o.total_value_purchased) AS total_purchased
FROM 
  Products p
  JOIN 
  (
    SELECT 
      product_id, 
      SUM(total_amount_purchased) AS total_value_purchased
    FROM 
      Product_Suppliers ps
      JOIN 
      Supplier_Addresses sa ON ps.supplier_id = sa.supplier_id
      JOIN 
      Suppliers s ON sa.supplier_id = s.supplier_id
    GROUP BY 
      product_id
  ) ps
  ON p.product_id = ps.product_id
GROUP BY 
  p.product_id, p.product_name
ORDER BY 
  total_purchased DESC
LIMIT 3;
```

