  Customer_Addresses CA ON C.customer_id = CA.customer_id
  JOIN 
  Supplier_Addresses SA ON C.customer_id = SA.customer_id
  JOIN 
  Department_Stores DS ON SA.address_id = DS.dept_store_chain_id
  JOIN 
  Department_Store_Chain DS2 ON DS.dept_store_chain_id = DS2.dept_store_id
