  Order_Items OI ON O.order_id = OI.order_id
  JOIN 
  Product_Suppliers PS ON OI.product_id = PS.product_id
WHERE 
  C.payment_method_code = 'PAYMENT'
GROUP BY 
  C.customer_id
ORDER BY 
  customer_count DESC;
