SELECT DISTINCT c.customer_name, c.address_details, COALESCE(s.supplier_name, 'Unknown') AS supplier_name, COALESCE(d.dept_store_chain_name, 'Unknown') AS dept_store_chain_name FROM Customers c JOIN Customer_Addresses ca ON c.customer_id = ca.customer_id JOIN Addresses a ON ca.address_id = a.address_id JOIN Supplier_Addresses sa ON a.address_id = sa.address_id JOIN Suppliers s ON sa.supplier_id = s.supplier_id JOIN Department_Stores d ON d.dept_store_id = d.dept_store_id JOIN Departments d ON d.dept_store_id = d.dept_store_id JOIN Customer_Orders co ON c.customer_id = co.customer_id JOIN Order_Items oi ON co.order_id = oi.order_id JOIN Product_Suppliers ps ON oi.product_id = ps.product_id JOIN Staff_Department_Assignments sa ON sa.staff_id = sa.staff_id WHERE co.order_status_code = 'Pending' GROUP BY c.customer_name, c.address_details, COALESCE(s.supplier_name, 'Unknown'), COALESCE(d.dept_store_chain_name, 'Unknown')
