SELECT 
  d.id AS department_id,
  COUNT(DISTINCT s.staff_id) AS staff_count
FROM 
  Department_Stores d
  JOIN Staff_Department_Assignments sd ON d.dept_store_id = sd.department_id
  JOIN Staff s ON sd.staff_id = s.staff_id
  JOIN Suppliers s ON s.supplier_id = sd.supplier_id
