SELECT 
  p.Product_Name, 
  COUNT(DISTINCT p.Product_Name) AS Most_Frequent_Status
FROM 
  Products p
  JOIN 
  Bookings_Services bs ON p.Product_ID = bs.Product_ID
  JOIN 
  Invoices IS ON bs.Product_ID = IS INvoices.Product_ID
  JOIN 
  Invoice_Items ii ON IS INvoices.Invoice_ID = ii.Invoice_ID
