{
  "sql": "SELECT c.customer_name, COALESCE(o.order_status_code, 'Unknown') AS order_status FROM Customers c JOIN Customer_Address_History ca ON c.customer_id = ca.customer_id JOIN Customer_Orders co ON c.customer_id = co.customer_id JOIN Order_Items oi ON co.order_id = oi.order_id JOIN Order o ON oi.order_id = o.order_id WHERE o.order_status_code IN ('Completed', 'Part') AND ca.address_id IN (SELECT address_id FROM Addresses WHERE state_province_county = 'State Province')",
}
