```sql
SELECT 
  h.star_rating_code,
  h.star_rating_description,
  h.price_range,
  t.Name AS Tourist_Attraction_Name
FROM 
  Hotels h
  JOIN 
  (SELECT 
     star_rating_code, 
     MIN(price_range) AS price_range 
   FROM 
     Hotels 
   GROUP BY 
     star_rating_code) AS subquery
  ON h.star_rating_code = (SELECT star_rating_code FROM subquery)
WHERE 
