SELECT 
  SUM(CASE 
    WHEN T1.Service_Type_Code = T2.Service_Type_Code 
    THEN T1.Order_Quantity 
  END) AS min_order_quantity,
  AVG(T1.Order_Quantity) AS avg_order_quantity,
  MAX(T1.Order_Quantity) AS max_order_quantity
FROM 
  Ref_Service_Types T1
  JOIN Invoices T2 ON T1.Service_Type_Code = T2.Service_Type_Code
