SELECT DISTINCT C.Currency_Code
FROM Drama_Workshop_Groups
JOIN Addresses ON Drama_Workshop_Groups.Address_ID = Addresses.Address_ID
JOIN Clients ON Drama_Workshop_Groups.Client_ID = Clients.Client_ID
