SELECT 
  f.form_name 
FROM 
  Party_Forms pf 
  JOIN 
  Party_Services ps 
  ON pf.form_id = ps.form_id 
  JOIN 
  Services s 
  ON ps.service_id = s.service_id 
  JOIN 
  Addresses a 
  ON pf.address_id = a.address_id 
  JOIN 
  Individuals i 
  ON a.individual_id = i.individual_id 
  JOIN 
  Organizations o 
  ON i.organization_id = o.organization_id 
WHERE 
  o.country = 'Canada' 
  AND o.state_province_county = 'Ontario' 
  AND o.uk_vat_number = '1234567890'
ORDER BY 
  f.form_name DESC
LIMIT 1;
