SELECT DISTINCT L.last_name
FROM Individuals
JOIN Organization_Contact_Individuals ON Individuals.individual_id = Organization_Contact_Individuals.individual_id
JOIN Parties ON Individuals.individual_id = Parties.party_id
JOIN Organizations ON Parties.organization_id = Organizations.organization_id
JOIN Addresses ON Organizations.organization_id = Addresses.address_id
JOIN Party_Addresses ON Addresses.address_id = Party_Addresses.address_id
